#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> s(n), t(m);
    for (string& x : s) {
        cin >> x;
    }
    for (string& x : t) {
        cin >> x;
    }
    set<string> rapid(t.begin(), t.end());
    for (const string& x : s) {
        cout << (rapid.count(x) ? "Yes" : "No") << '\n';
    }
}
